import { CONFIG } from './config.js';
import { TOOLS, TOOL_IDS, TOOL_BY_ID, FLOW_ORDER, icon } from './core/tools.js';
import { DemoStore, STATUS, escapeHTML as esc, localDay, shiftDay, formatDay, toolStats, csv, validatePhone, makeWhatsAppMessage, buildShareUrl } from './core/store.js';
import { Demonstration } from './core/demonstration.js';
import { suggestTools, readDocument, answerMessage } from './core/assistants.js';

let storage=null;try{storage=window.localStorage;}catch{}
const catalogStore=new DemoStore({storage,key:CONFIG.storageKey});
let store=catalogStore,workspaceTools=[],unsubscribe,demonstration=null;
let aiSuggestions=[], aiMode='atendimento';
const params=new URL(window.location.href).searchParams;
const referral=(params.get('parceiro')||'').slice(0,80);
if(params.has('f')) store.selectTools((params.get('f')||'').split(','));
if(params.get('embed')==='1')document.body.classList.add('embedded');
let settings={...CONFIG};try{const saved=JSON.parse(storage?.getItem(CONFIG.configKey)||'{}');if(validatePhone(saved.whatsappNumber))settings.whatsappNumber=saved.whatsappNumber;}catch{}
let toolFilter='todas',search='',serviceFilter='todos',appointmentFilter='todos',appointmentDate='',indicatorPeriod='todos';
let toastTimer,proofPhoto='',drawerOpen=false;
let draft={name:'',company:'',role:'',need:''};
const main=document.getElementById('conteudo'),modal=document.getElementById('modal');
const route=()=>{const id=location.hash.replace(/^#/,'');if(id.startsWith('demo-'))return 'demonstracao';return ['inicio','ferramentas','solucao','personalizada','automacoes',...TOOL_IDS].includes(id)?id:'inicio';};
const badge=status=>`<span class="pill ${Object.hasOwn(STATUS,status)?status:''}">${esc(STATUS[status]||status)}</span>`;
const smallAction=(action,id,label,kind='soft')=>`<button class="btn ${kind} small" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const demoNotice=()=>`<div class="demo-notice">${icon('globe')}<span><strong>Dados fictícios.</strong> Experimente à vontade. Preencha, acompanhe e veja os resultados.</span><button class="text-button" data-action="reset">Restaurar</button></div>`;
const empty=(title,detail='',symbol='spark')=>`<div class="empty">${icon(symbol)}${title}${detail?`<p>${detail}</p>`:''}</div>`;
const time=at=>new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit',day:'2-digit',month:'2-digit'}).format(new Date(at));
const selectionButton=id=>`<button class="btn ${store.state.selected.includes(id)?'success':'soft'}" data-action="toggle-tool" data-id="${id}" aria-pressed="${store.state.selected.includes(id)}">${icon(store.state.selected.includes(id)?'check':'plus')}${store.state.selected.includes(id)?'Na minha solução':'Adicionar à solução'}</button>`;
const toolHead=id=>{if(workspaceTools.length)return '';const tool=TOOL_BY_ID[id];return `<div class="breadcrumb"><a href="#ferramentas">Ferramentas</a> / <span>${esc(tool.short)}</span></div><div class="page-head"><div><div class="eyebrow">Ferramenta ${String(TOOL_IDS.indexOf(id)+1).padStart(2,'0')} / 08</div><h1>${esc(tool.name)}</h1><p>${esc(tool.description)}</p></div>${selectionButton(id)}</div>${demoNotice()}`;};
const field=(name,label,{type='text',placeholder='',required=true,value='',min='',max='',step='',autocomplete='',textarea=false,options=null}={})=>`<div class="field"><label for="${name}">${label}</label>${textarea?`<textarea id="${name}" name="${name}" maxlength="1800" placeholder="${esc(placeholder)}" ${required?'required':''}>${esc(value)}</textarea>`:options?`<select id="${name}" name="${name}" ${required?'required':''}>${options.map(item=>`<option value="${esc(typeof item==='string'?item:item.value)}"${(typeof item==='string'?item:item.value)===value?' selected':''}>${esc(typeof item==='string'?item:item.label)}</option>`).join('')}</select>`:`<input id="${name}" name="${name}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${required?'required':''} ${min?`min="${min}"`:''} ${max?`max="${max}"`:''} ${step?`step="${step}"`:''} ${autocomplete?`autocomplete="${autocomplete}"`:''} ${type==='text'?'maxlength="200"':''}>`}</div>`;
function toast(message){const node=document.getElementById('toast');node.textContent=message;node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.hidden=true,4500);}
function notify(message){toast(store.persistent?message:message+' Alteração disponível nesta visita; o armazenamento do navegador está indisponível.');}
function openModal(title,html){document.getElementById('modal-title').textContent=title;document.getElementById('modal-content').innerHTML=html;if(!modal.open)modal.showModal();}
function download(content,filename,type='text/csv;charset=utf-8'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function nav(){const current=route(),selected=store.state.selected;document.getElementById('navigation').innerHTML=`<a class="nav-link ${current==='inicio'?'active':''}" href="#inicio"${current==='inicio'?' aria-current="page"':''}>${icon('home')}<span>Visão geral</span></a><a class="nav-link ${current==='solucao'?'active':''}" href="#solucao"${current==='solucao'?' aria-current="page"':''}>${icon('workflow')}<span>Monte sua solução</span><span class="nav-count">${selected.length}</span></a><div class="nav-label">Explore as ferramentas</div>${TOOLS.map(tool=>`<a class="nav-link tool-link ${current===tool.id?'active':''}" href="#${tool.id}"${current===tool.id?' aria-current="page"':''}>${icon(tool.icon)}<span>${esc(tool.name)}</span>${selected.includes(tool.id)?'<span class="nav-selected" title="Selecionada"></span>':''}</a>`).join('')}<a class="nav-link ${current==='automacoes'?'active':''}" href="#automacoes">${icon('spark')}<span>Exemplos com IA</span></a>`;
  document.querySelector('.custom-nav').setAttribute('aria-current',current==='personalizada'?'page':'false');
  document.getElementById('topbar-title').textContent=TOOL_BY_ID[current]?.short||({inicio:'Ferramentas Horizon',ferramentas:'Todas as ferramentas',solucao:'Monte sua solução',personalizada:'Sua ferramenta personalizada',automacoes:'Exemplos com IA'})[current];
  const selectionBar=document.getElementById('selection-bar');selectionBar.hidden=!selected.length||current==='solucao'||current==='personalizada';selectionBar.innerHTML=`<div><strong>${selected.length} ferramenta${selected.length===1?'':'s'} escolhida${selected.length===1?'':'s'}</strong><small>Veja como podem trabalhar juntas.</small></div><a class="btn primary" href="#solucao">Montar solução ${icon('arrow')}</a>`;document.body.classList.toggle('has-selection',!selectionBar.hidden);
}
function toolCards(items=TOOLS) {
  return items.map(tool=>{
    const selected=catalogStore.state.selected.includes(tool.id);
    return `<article class="tool-card ${selected?'selected':''}">
      <div class="tool-card-top"><span class="tool-icon">${icon(tool.icon)}</span><span class="tool-number">${String(TOOL_IDS.indexOf(tool.id)+1).padStart(2,'0')} / 08</span></div>
      <h3>${esc(tool.name)}</h3><p>${esc(tool.description)}</p>
      <div class="tool-card-bottom"><div class="tool-card-links">
        <a class="text-button" href="#${tool.id}">Experimentar ${icon('arrow')}</a>
        <button class="text-button demo-link" data-action="demo-tool" data-id="${tool.id}">${icon('workflow')}Ver demonstração</button>
      </div><button class="add-button ${selected?'chosen':''}" data-action="toggle-tool" data-id="${tool.id}" aria-pressed="${selected}" aria-label="${selected?'Remover':'Adicionar'} ${esc(tool.name)} ${selected?'da':'à'} solução">${icon(selected?'check':'plus')}${selected?'Escolhida':'Adicionar'}</button></div>
    </article>`;
  }).join('');
}
function banner(){return `<div class="custom-banner"><div class="tool-icon">${icon('spark')}</div><div><h3>Sua necessidade não cabe numa lista?</h3><p>Conte seu problema. Criamos uma solução para sua empresa.</p></div><a class="btn secondary small" href="#personalizada">Criar ferramenta personalizada ${icon('arrow')}</a></div>`;}
function home(){const stats=toolStats(store.state);return `<section class="hero"><div><div class="eyebrow">Ferramentas que se conectam</div><h1>Sua empresa,<br><span>seu sistema.</span></h1><p class="hero-description">Escolha as ferramentas que precisa.<br>Nós conectamos e personalizamos tudo para você.</p><div class="hero-buttons"><a class="btn primary" href="#ferramentas">Explorar ferramentas ${icon('arrow')}</a><a class="btn secondary" href="#solucao">Monte sua solução</a></div><p class="microcopy">${icon('check')}Experimente sem cadastro. Tudo no seu ritmo.</p></div><div class="hero-live" aria-label="Exemplo: um checklist pode atualizar serviços, planilhas e indicadores"><div class="live-floating">${icon('link')}Um registro. Várias conexões.</div><div class="live-stack"><a class="live-card" href="#checklists"><span class="live-icon">${icon('checklist')}</span><div><strong>Checklist de conferência</strong><small>${store.state.inspection.status==='concluido'?'Conferência concluída':'Confira os itens pelo celular'}</small></div><span class="live-status">${icon(store.state.inspection.status==='concluido'?'check':'arrow')}</span></a><a class="live-card" href="#planilhas"><span class="live-icon">${icon('table')}</span><div><strong>Planilha atualizada</strong><small>${stats.rows} registros na demonstração</small></div><span class="live-status preview-arrow">${icon('arrow')}</span></a><a class="live-card" href="#indicadores"><span class="live-icon">${icon('chart')}</span><div><strong>Resultados à vista</strong><small>${stats.completed} de ${stats.services} serviços concluídos</small></div><span class="live-status preview-arrow">${icon('arrow')}</span></a></div><span class="live-caption">Exemplo interativo · dados fictícios</span></div></section><div class="strip">${icon('workflow')}<p><strong>Uma ferramenta já ajuda. Juntas, vão além.</strong> Combine o que faz sentido para sua rotina.</p><button class="text-button" data-action="example-solution">Ver uma conexão ${icon('arrow')}</button></div><section aria-labelledby="tools-heading"><div class="section-header"><div><h2 id="tools-heading">Experimente o que resolve.</h2><p>Toque em uma ferramenta e veja na prática.</p></div><span class="section-tag">08 ferramentas · infinitas combinações</span></div><div class="tool-grid">${toolCards()}</div></section>${aiBanner()}${banner()}`;}
function filteredTools(){const normalized=value=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return TOOLS.filter(tool=>(toolFilter==='todas'||tool.category===toolFilter)&&normalized(tool.name+' '+tool.description+' '+tool.tags.join(' ')).includes(normalized(search)));}
function gallery(){const items=filteredTools();return `<div class="page-head"><div><div class="eyebrow">Ferramentas Horizon</div><h1>Escolha o que sua empresa precisa.</h1><p>Experimente uma ferramenta. Combine várias. Personalize tudo.</p></div></div><div class="search-row"><div class="filters" aria-label="Filtrar ferramentas">${[['todas','Todas'],['operacao','Operação'],['registros','Registros'],['resultados','Resultados']].map(([id,label])=>`<button class="filter ${toolFilter===id?'active':''}" data-action="tool-filter" data-id="${id}" aria-pressed="${toolFilter===id}">${label}</button>`).join('')}</div><label class="search-field">${icon('search')}<input type="search" id="tool-search" value="${esc(search)}" placeholder="Buscar uma necessidade" aria-label="Buscar ferramentas"></label></div><p class="search-count" id="search-count">${items.length} ferramentas para explorar</p><div class="tool-grid" id="tool-gallery">${items.length?toolCards(items):empty('Nenhuma ferramenta encontrada.','Descreva sua necessidade em Criar ferramenta personalizada.','search')}</div>${banner()}`;}
function sheets(){const rows=store.state.rows;return `${toolHead('planilhas')}<div class="demo-layout"><div class="stack"><form class="panel" id="record-form"><h2>Registre uma informação</h2><p class="panel-subtitle">Preencha e veja uma nova linha aparecer na planilha.</p>${field('title','Registro',{placeholder:'Ex.: Material recebido'})}<div class="form-row">${field('quantity','Quantidade',{type:'number',value:'1',min:'1',max:'999999',step:'1'})}${field('owner','Responsável',{placeholder:'Ex.: Marina'})}</div><button class="btn primary full-width" type="submit">Registrar e atualizar ${icon('arrow')}</button><p class="form-hint">Seu registro aparece imediatamente na planilha.</p></form><div class="benefit-box"><strong>Preencher uma vez basta.</strong><p>${store.enabled('servicos')||store.enabled('checklists')?'Conferências e serviços conectados também atualizam estes registros.':'As informações ficam organizadas e prontas para consultar.'}</p></div></div><section class="panel"><div class="panel-top"><h2>Planilha de registros</h2><span class="panel-count">${rows.length} linhas</span></div><div class="table-wrap" tabindex="0" aria-label="Planilha demonstrativa, role para ver as colunas"><table><thead><tr><th>REGISTRO</th><th>ORIGEM</th><th>QTD.</th><th>RESPONSÁVEL</th><th>SITUAÇÃO</th><th>AÇÃO</th></tr></thead><tbody>${rows.map(row=>`<tr><td><strong>${esc(row.title)}</strong></td><td>${esc(row.type)}</td><td>${esc(row.quantity)}</td><td>${esc(row.owner)}</td><td>${badge(row.status)}</td><td>${row.type==='Registro'?`<button class="text-button danger" data-action="remove-record" data-id="${esc(row.id)}" aria-label="Remover registro ${esc(row.title)}">Remover</button>`:'—'}</td></tr>`).join('')}</tbody></table></div><div class="table-toolbar"><p>Dados fictícios · atualizado a cada ação</p><button class="btn secondary small" data-action="export-rows">${icon('download')}Baixar planilha</button></div></section></div>`;}
function services(){const items=store.state.services.filter(item=>serviceFilter==='todos'||item.status===serviceFilter);return `${toolHead('servicos')}<div class="filters" aria-label="Filtrar serviços">${[['todos','Todos'],['solicitado','Solicitados'],['andamento','Em andamento'],['pendente','Pendentes'],['concluido','Concluídos']].map(([id,label])=>`<button class="filter ${serviceFilter===id?'active':''}" data-action="service-filter" data-id="${id}" aria-pressed="${serviceFilter===id}">${label}</button>`).join('')}</div><div class="demo-layout"><form id="service-form" class="panel"><h2>Solicite um serviço</h2><p class="panel-subtitle">Crie um exemplo e acompanhe cada mudança.</p>${field('title','Serviço',{placeholder:'Ex.: Revisão dos equipamentos'})}${field('client','Empresa ou unidade',{placeholder:'Ex.: Unidade Centro'})}${field('owner','Responsável',{placeholder:'Ex.: Lucas'})}${field('due','Prazo',{type:'date',value:localDay()})}<button class="btn primary full-width" type="submit">Criar solicitação ${icon('plus')}</button></form><section class="panel"><div class="panel-top"><h2>Serviços acompanhados</h2><span class="panel-count">${items.length} serviços</span></div><div class="record-list">${items.length?items.map(item=>`<article class="record-card"><div class="record-card-top"><h3>${esc(item.title)}</h3>${badge(item.status)}</div><div class="record-meta"><span>${esc(item.client)}</span><span>${esc(item.owner)}</span><span>${icon('clock')}${formatDay(item.due)}${item.status!=='concluido'&&item.due<localDay()?' · prazo vencido':''}</span></div><div class="record-actions">${item.status==='solicitado'?smallAction('start-service',item.id,'Iniciar serviço'):item.status==='andamento'?smallAction('complete-service',item.id,'Concluir serviço'):item.status==='pendente'?smallAction('start-service',item.id,'Retomar serviço'):''}${item.status==='andamento'?smallAction('pause-service',item.id,'Marcar pendência','secondary'):''}<button class="text-button" data-action="service-history" data-id="${esc(item.id)}">Ver histórico</button></div></article>`).join(''):empty('Nenhum serviço nesta situação.','Crie um exemplo ou use outro filtro.','briefcase')}</div></section></div>`;}
function checklists(){const item=store.state.inspection,done=item.items.filter(item=>item.done).length,finished=item.status==='concluido',progress=Math.round(done/item.items.length*100),linked=store.state.services.find(service=>service.id===item.serviceId);return `${toolHead('checklists')}<div class="demo-layout equal"><section class="panel"><div class="panel-top"><h2>${esc(item.title)}</h2>${badge(item.status)}</div><p class="panel-subtitle">Responsável: ${esc(item.owner)} · ${esc(linked?.client||'Unidade Exemplo')}</p><div class="progress-heading"><span>${done} de ${item.items.length} itens conferidos</span><strong>${progress}%</strong></div><div class="progress" role="progressbar" aria-valuenow="${progress}" aria-valuemin="0" aria-valuemax="100" aria-label="Checklist conferido"><span style="width:${progress}%"></span></div>${item.items.map(check=>`<label class="check-item ${check.done?'checked':''}"><input type="checkbox" id="inspection-${esc(check.id)}" data-inspection="${esc(check.id)}" ${check.done?'checked':''} ${finished?'disabled':''}><span>${esc(check.text)}</span></label>`).join('')}<div class="field" style="margin-top:19px"><label for="inspection-notes">Observações <span class="user-note">(opcional)</span></label><textarea id="inspection-notes" maxlength="1200" placeholder="Registre o que merece atenção." ${finished?'disabled':''}>${esc(item.notes)}</textarea></div>${finished?`<div class="inspection-success">${icon('check')} Conferência concluída.<p>${esc(connectionSummary(['servicos','planilhas','indicadores']))}</p></div><button class="btn secondary full-width" data-action="new-inspection" style="margin-top:12px">Nova inspeção ${icon('plus')}</button>`:`<button class="btn primary full-width" data-action="complete-inspection" ${done===item.items.length?'':'disabled'}>Concluir checklist ${icon('check')}</button><p class="form-hint">Confira os quatro itens para habilitar a conclusão.</p>`}</section><div class="stack"><section class="panel"><h2>${store.enabled('servicos')||store.enabled('planilhas')||store.enabled('indicadores')?'A conferência conecta os resultados.':'Sua conferência, registrada.'}</h2><p class="panel-subtitle">Preencha, conclua e acompanhe o resultado.</p><div class="connection-list">${[['checklists','Checklist','Conferência registrada'],['servicos','Serviço','Situação atualizada'],['planilhas','Planilha','Registro automático'],['indicadores','Indicadores','Resultado recalculado']].filter(([id])=>store.enabled(id)).map(([id,title,detail])=>`<a class="connection-item" href="#${id}"><span class="tool-icon">${icon(TOOL_BY_ID[id].icon)}</span><span><strong>${title}</strong><small>${detail}</small></span>${icon(finished?'check':'arrow','right-check')}</a>`).join('')}</div></section><section class="panel"><div class="panel-top"><h2>Histórico de inspeções</h2><span class="panel-count">${store.state.inspections.length} concluídas</span></div>${store.state.inspections.length?`<ul class="timeline">${store.state.inspections.slice(0,6).map(record=>`<li>${esc(record.title)} · ${esc(record.owner)}<time>${time(record.at)}</time></li>`).join('')}</ul>`:empty('A primeira conferência aparece aqui.','Conclua o checklist para registrar o histórico.','checklist')}</section></div></div>`;}
function appointments(){const items=store.state.appointments.filter(item=>(appointmentFilter==='todos'||item.status===appointmentFilter)&&(!appointmentDate||item.date===appointmentDate)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return `${toolHead('agendamentos')}<div class="demo-layout"><form class="panel" id="appointment-form"><h2>Agende um compromisso</h2><p class="panel-subtitle">Atendimento, visita ou retorno. Com responsável e prazo.</p>${field('title','Compromisso',{placeholder:'Ex.: Retorno da proposta'})}${field('company','Empresa ou unidade',{placeholder:'Ex.: Empresa Exemplo'})}<div class="form-row">${field('kind','Tipo',{options:['Retorno','Visita','Atendimento']})}${field('owner','Responsável',{placeholder:'Ex.: Marina'})}</div><div class="form-row">${field('date','Data',{type:'date',value:localDay(),min:localDay()})}${field('time','Horário',{type:'time',value:'09:00'})}</div><button class="btn primary full-width" type="submit">Agendar compromisso ${icon('calendar')}</button></form><section class="panel"><div class="panel-top"><h2>Agenda de exemplo</h2><button class="text-button" data-action="all-dates">Todas as datas</button></div><div class="calendar-strip">${[0,1,2,3,4].map(offset=>{const day=shiftDay(localDay(),offset),date=new Date(day+'T12:00:00');return `<button class="day-button ${appointmentDate===day?'active':''}" data-action="appointment-day" data-id="${day}" aria-pressed="${appointmentDate===day}" aria-label="Mostrar ${formatDay(day)}"><small>${offset===0?'Hoje':date.toLocaleDateString('pt-BR',{weekday:'short'})}</small><strong>${date.getDate()}</strong>${store.state.appointments.some(item=>item.date===day&&item.status==='marcado')?'<span></span>':''}</button>`;}).join('')}</div><div class="filters">${[['todos','Todos'],['marcado','Agendados'],['concluido','Concluídos']].map(([id,label])=>`<button class="filter ${appointmentFilter===id?'active':''}" data-action="appointment-filter" data-id="${id}">${label}</button>`).join('')}</div><div class="record-list">${items.length?items.map(item=>`<article class="record-card appointment-card"><div class="appointment-time">${esc(item.time)}<small>${formatDay(item.date)}</small></div><div class="appointment-content"><div class="record-card-top"><h3>${esc(item.title)}</h3>${badge(item.status)}</div><div class="record-meta"><span>${esc(item.kind)}</span><span>${esc(item.company)}</span><span>${esc(item.owner)}</span></div>${item.status==='marcado'?`<div class="record-actions">${smallAction('appointment-complete',item.id,'Concluir')}${smallAction('appointment-postpone',item.id,'Adiar 1 dia','secondary')}</div>`:''}</div></article>`).join(''):empty('Nenhum compromisso neste filtro.','Agende um exemplo ou escolha outra data.','calendar')}</div></section></div>`;}
function approvals(){return `${toolHead('etapas')}<form class="panel" id="approval-form"><h2>Comece um processo</h2><div class="form-row">${field('title','Solicitação',{placeholder:'Ex.: Aprovar uma compra'})}${field('owner','Responsável pela aprovação',{placeholder:'Ex.: Rafael'})}</div><button class="btn primary small" type="submit">Adicionar solicitação ${icon('plus')}</button></form><div class="kanban">${[['solicitacao','Solicitação'],['aprovacao','Em aprovação'],['concluido','Concluído']].map(([stage,title])=>{const items=store.state.approvals.filter(item=>item.stage===stage);return `<section class="kanban-column"><div class="kanban-title">${title}<span>${items.length}</span></div>${items.length?items.map(item=>`<article class="record-card"><h3>${esc(item.title)}</h3><div class="record-meta"><span>${esc(item.owner)}</span></div>${stage!=='concluido'?`<div class="record-actions">${smallAction('approval-advance',item.id,stage==='solicitacao'?'Enviar para aprovação':'Aprovar')}${stage==='aprovacao'?`<button class="text-button" data-action="approval-adjust" data-id="${esc(item.id)}">Solicitar ajuste</button>`:''}</div>`:`<span class="proof-stamp">${icon('check')}Processo finalizado</span>`}</article>`).join(''):empty('Nenhum processo aqui.','','workflow')}</section>`;}).join('')}</div><p class="form-hint">As aprovações são fictícias. Em uma solução real, cada etapa pode ter suas próprias permissões.</p>`;}
function incidents(){const items=store.state.incidents;return `${toolHead('ocorrencias')}<div class="demo-layout"><form class="panel" id="incident-form"><h2>Registre uma ocorrência</h2><p class="panel-subtitle">Defina o problema e quem vai resolvê-lo.</p>${field('title','Problema ou solicitação',{placeholder:'Ex.: Equipamento com falha'})}${field('place','Local',{placeholder:'Ex.: Unidade Norte'})}${field('owner','Responsável',{placeholder:'Ex.: Lucas'})}${field('priority','Prioridade',{options:[{value:'normal',label:'Normal'},{value:'alta',label:'Alta'}]})}<button class="btn primary full-width" type="submit">Registrar ocorrência ${icon('flag')}</button></form><section class="panel"><div class="panel-top"><h2>Solicitações acompanhadas</h2><span class="panel-count">${items.filter(item=>item.status!=='resolvido').length} em aberto</span></div><div class="record-list">${items.map(item=>`<article class="record-card"><div class="record-card-top"><h3>${esc(item.title)}</h3>${badge(item.status)}</div><div class="record-meta"><span>${esc(item.place)}</span><span>Responsável: ${esc(item.owner)}</span>${item.priority==='alta'?'<span class="pill alta">Prioridade alta</span>':''}</div>${item.status!=='resolvido'?`<div class="record-actions">${smallAction('incident-next',item.id,item.status==='aberto'?'Encaminhar ao responsável':'Marcar como resolvida')}</div>`:''}</article>`).join('')}</div></section></div>`;}
function indicators() {
  const stats=toolStats(store.state,indicatorPeriod==='hoje');
  const standalone=store.tools.length===1&&store.enabled('indicadores');
  const has=id=>standalone||store.enabled(id);
  const metrics=[
    ['servicos','Serviços concluídos',stats.completed,'De '+stats.services+' serviços','briefcase'],
    ['ocorrencias','Ocorrências abertas',stats.openIncidents,'Abertas ou encaminhadas','flag'],
    ['checklists','Inspeções concluídas',stats.inspections,'Conferências registradas','checklist'],
    ['agendamentos','Compromissos agendados',stats.appointments,'Visitas, retornos e atendimentos','calendar'],
    ['etapas','Processos aprovados',store.state.approvals.filter(i=>i.stage==='concluido'&&(indicatorPeriod!=='hoje'||localDay(new Date(i.at))===localDay())).length,'Etapas concluídas','workflow'],
    ['planilhas','Registros em planilha',stats.rows,'Informações organizadas','table'],
    ['comprovantes','Comprovantes registrados',stats.proofs,'Execuções confirmadas','receipt']
  ].filter(([id])=>has(id));
  return `${toolHead('indicadores')}<div class="panel-top"><div class="filters" style="margin:0"><button class="filter ${indicatorPeriod==='todos'?'active':''}" data-action="indicator-period" data-id="todos">Todos os registros</button><button class="filter ${indicatorPeriod==='hoje'?'active':''}" data-action="indicator-period" data-id="hoje">Hoje</button></div><button class="btn secondary small" data-action="export-report">${icon('download')}Baixar relatório</button></div>
    <div class="metric-grid">${metrics.map(([,label,value,detail,symbol])=>`<article class="metric"><div class="metric-label">${label}${icon(symbol)}</div><strong>${value}</strong><small>${detail}</small></article>`).join('')}</div>
    <div class="chart-layout">${has('servicos')?`<section class="panel"><h2>Como estão os serviços?</h2><p class="panel-subtitle">Resultados dos serviços registrados nesta demonstração.</p>${Object.entries(stats.statuses).map(([status,count])=>`<div class="bar-row"><span>${STATUS[status]}</span><div class="bar-track"><div class="bar-fill ${status}" style="width:${stats.services?Math.round(count/stats.services*100):0}%"></div></div><strong>${count}</strong></div>`).join('')}<p class="chart-note">${stats.completed} de ${stats.services} serviços concluídos.</p></section>`:`<section class="panel"><h2>Resultados da operação</h2><p class="panel-subtitle">Contagens dos registros das ferramentas escolhidas.</p>${metrics.map(([,label,value])=>`<div class="summary-row"><span>${label}</span><strong>${value}</strong></div>`).join('')}</section>`}
    <section class="panel"><h2>Últimas atividades</h2><p class="panel-subtitle">Cada mudança fica registrada no histórico.</p>${store.state.events.filter(item=>indicatorPeriod!=='hoje'||localDay(new Date(item.at))===localDay()).length?`<ul class="timeline">${store.state.events.filter(item=>indicatorPeriod!=='hoje'||localDay(new Date(item.at))===localDay()).slice(0,8).map(item=>`<li>${esc(item.text)}<time>${time(item.at)}</time></li>`).join('')}</ul>`:empty('Nenhuma atividade neste período.','Experimente uma ação para acompanhar o resultado.')}</section></div>`;
}
function proofs(){return `${toolHead('comprovantes')}<div class="demo-layout"><form class="panel" id="proof-form"><h2>Confirme uma execução</h2><p class="panel-subtitle">Deixe observações e uma foto opcional.</p>${store.enabled('servicos')?field('serviceId','Serviço',{options:store.state.services.map(item=>({value:item.id,label:item.title}))}):field('title','Atividade realizada',{placeholder:'Ex.: Conferência dos materiais'})}${field('owner','Responsável pela execução',{placeholder:'Ex.: Marina'})}${field('notes','O que foi realizado?',{textarea:true,placeholder:'Descreva a execução e o resultado.'})}<div class="photo-upload"><label for="proof-photo">${icon('photo')}Adicionar foto</label><input id="proof-photo" type="file" accept="image/jpeg,image/png,image/webp"><small>Opcional · a foto fica somente neste navegador.</small><div id="photo-preview" class="photo-preview">${proofPhoto?`<img src="${proofPhoto}" alt="Foto selecionada para o comprovante">`:''}</div></div><button class="btn primary full-width" type="submit">Registrar execução ${icon('check')}</button></form><section class="panel"><div class="panel-top"><h2>Execuções registradas</h2><span class="panel-count">${store.state.proofs.length} comprovantes</span></div><div class="record-list">${store.state.proofs.slice(0,10).map(item=>`<article class="record-card proof-card">${item.photo?`<img class="proof-thumb" src="${/^data:image\/(jpeg|png|webp);base64,/.test(item.photo)?esc(item.photo):''}" alt="Foto da execução de ${esc(item.title)}">`:''}<div class="record-card-top"><h3>${esc(item.title)}</h3>${badge('concluido')}</div><p>${esc(item.notes)}</p><span class="proof-stamp">${icon('check')}${esc(item.owner)} · ${time(item.at)}</span><div class="record-actions">${smallAction('view-proof',item.id,'Ver comprovante','secondary')}<button class="text-button" data-action="download-proof" data-id="${esc(item.id)}">${icon('download')}Baixar</button></div></article>`).join('')}</div></section></div>`;}
function solution() {
  const selected=catalogStore.state.selected;
  return `<div class="page-head"><div><div class="eyebrow">Sua combinação de ferramentas</div><h1>Monte sua solução.</h1><p>Escolha o que precisa e use um aplicativo com essas ferramentas.</p></div></div>
    <div class="solution-layout"><section class="panel"><div class="panel-top"><h2>Escolha suas ferramentas</h2><span class="panel-count">${selected.length} escolhidas</span></div>
    ${TOOLS.map(tool=>`<label class="solution-select ${selected.includes(tool.id)?'checked':''}"><span class="tool-icon">${icon(tool.icon)}</span><span><strong>${esc(tool.name)}</strong><small>${esc(tool.benefit)}</small></span><input type="checkbox" id="select-${tool.id}" data-select="${tool.id}" ${selected.includes(tool.id)?'checked':''} aria-label="Selecionar ${esc(tool.name)}"></label>`).join('')}</section>
    <section class="panel flow-panel"><div class="eyebrow">Ferramentas Horizon</div><h2>${selected.length?'As ferramentas da sua solução.':'O aplicativo começa com a sua escolha.'}</h2><p>${selected.length?'Um só aplicativo. Registros compartilhados entre as ferramentas escolhidas.':'Marque uma ou mais ferramentas para montar seu exemplo.'}</p>
    <div class="flow-sequence">${FLOW_ORDER.filter(id=>selected.includes(id)).map(id=>`<div class="flow-node"><span class="tool-icon">${icon(TOOL_BY_ID[id].icon)}</span><span><strong>${esc(TOOL_BY_ID[id].short)}</strong><small>${esc(TOOL_BY_ID[id].benefit)}</small></span></div>`).join('')||empty('Escolha o que resolve sua rotina.','Cada ferramenta pode funcionar sozinha.')}</div>
    <div class="solution-bottom"><button class="btn primary full-width" data-action="launch-demo" ${selected.length?'':'disabled'}>${icon('workflow')}Montar solução ${icon('arrow')}</button>
    <button class="btn secondary full-width" data-action="launch-guided" ${selected.length?'':'disabled'}>Ver demonstração guiada ${icon('arrow')}</button>
    ${selected.length?'<a class="text-button request-link" href="#personalizada">Quero essa solução</a>':'<button class="text-button request-link" data-action="example-solution">Usar exemplo de uma operação</button>'}</div>
    <p class="form-hint">Formulários, etapas, planilha e relatórios prontos para experimentar. Dados de exemplo.</p></section></div>`;
}
function enterWorkspace(ids=catalogStore.state.selected, guided=false) {
  const chosen=FLOW_ORDER.filter(id=>ids.includes(id));
  if(!chosen.length)return false;
  workspaceTools=chosen;
  unsubscribe?.();
  store=new DemoStore({storage,key:CONFIG.storageKey+':solution:v2:'+chosen.slice().sort().join('-'),tools:chosen});
  store.state.selected=[...chosen];
  store.commit(false);
  demonstration=guided?new Demonstration(chosen):null;
  unsubscribe=store.subscribe(()=>render());
  proofPhoto='';
  serviceFilter='todos';appointmentFilter='todos';appointmentDate='';indicatorPeriod='todos';
  return true;
}
function leaveWorkspace() {
  unsubscribe?.();store=catalogStore;workspaceTools=[];demonstration=null;proofPhoto='';
  serviceFilter='todos';appointmentFilter='todos';appointmentDate='';indicatorPeriod='todos';
  unsubscribe=store.subscribe(()=>render());
}
function workspace() {
  if(!workspaceTools.length&&!enterWorkspace())return solution();
  let active=location.hash.slice(6);
  if(!workspaceTools.includes(active))active=workspaceTools[0];
  const links=workspaceTools.map(id=>`<a class="demo-tab ${active===id?'active':''}" href="#demo-${id}" ${active===id?'aria-current="page"':''}>${icon(TOOL_BY_ID[id].icon)}${esc(TOOL_BY_ID[id].short)}</a>`).join('');
  let content=views[active]();
  content=content.replace(/<a([^>]*?)href="#([^" ]+)"([^>]*)>([\s\S]*?)<\/a>/g,(all,a,id,b,body)=>TOOL_IDS.includes(id)?(workspaceTools.includes(id)?`<a${a}href="#demo-${id}"${b}>${body}</a>`:''):all);
  return `<section class="assembled-app"><div class="assembled-header"><div><div class="eyebrow">Ferramentas Horizon · sua solução</div><h1>Minha operação</h1><p>${workspaceTools.length} ferramenta${workspaceTools.length===1?'':'s'} · dados de exemplo</p></div><div class="workspace-actions"><button class="btn secondary small" data-action="exit-demo">Alterar ferramentas</button><button class="btn primary small" data-action="request-workspace">Quero essa solução ${icon('arrow')}</button></div></div>
    <nav class="demo-tabs" aria-label="Ferramentas do seu aplicativo">${links}</nav>${guidePanel()}
    <div class="workspace-tip">${icon('link')}<span>${workspaceTools.length===1?'Preencha os exemplos abaixo e veja o resultado.':'Preencha uma vez. Abra as outras ferramentas para acompanhar as atualizações.'}</span>${!demonstration?'<button class="text-button" data-action="start-guide">Ver demonstração guiada</button>':''}</div>
    <div class="assembled-content">${content}</div></section>`;
}

function request(){return `<div class="page-head"><div><div class="eyebrow">Feito para a sua empresa</div><h1>Criar ferramenta personalizada.</h1><p>Não encontrou o que precisa? Conte seu problema. Criamos uma solução para sua empresa.</p></div></div><div class="personal-layout"><form class="panel" id="request-form"><h2>Conte sua ideia</h2><p class="panel-subtitle">Pode ser uma ferramenta ou uma solução com várias delas.</p><div class="form-row">${field('name','Seu nome',{value:draft.name,placeholder:'Como podemos chamar você?',autocomplete:'name'})}${field('company','Empresa',{value:draft.company,placeholder:'Nome da empresa',autocomplete:'organization'})}</div>${field('role','Cargo ou função',{value:draft.role,placeholder:'Sua função na empresa',autocomplete:'organization-title'})}<hr class="form-divider"><div class="form-label">Ferramentas escolhidas <span class="user-note">(opcional)</span></div><div class="request-tools">${TOOLS.map(tool=>`<label class="request-tool ${store.state.selected.includes(tool.id)?'checked':''}"><input type="checkbox" id="request-${tool.id}" data-select="${tool.id}" ${store.state.selected.includes(tool.id)?'checked':''}>${esc(tool.short)}</label>`).join('')}</div>${field('need','Descreva sua necessidade',{value:draft.need,textarea:true,placeholder:'Ex.: Preciso acompanhar as visitas da equipe e receber uma confirmação com foto.'})}<button class="btn primary full-width" type="submit">${icon('message')}Enviar minha ideia pelo WhatsApp</button><button class="text-button" type="button" data-action="preview-message" style="margin-top:13px">Conferir a mensagem antes ${icon('arrow')}</button><p class="form-hint">O WhatsApp abrirá com a mensagem pronta. Você confirma o envio por lá.</p><div id="whatsapp-fallback" hidden></div></form><aside class="request-side"><div class="panel"><h2>O seu processo<br>é o ponto de partida.</h2><p>Conte o que toma tempo, gera retrabalho ou precisa de controle. Nós traduzimos sua necessidade em uma solução.</p>${[['01','Você conta a necessidade','Com ou sem ferramentas escolhidas.'],['02','Nós entendemos a sua rotina','E propomos as conexões que fazem sentido.'],['03','A solução ganha a sua cara','Campos, etapas, responsáveis e visual.']].map(([number,title,detail])=>`<div class="request-step"><span>${number}</span><div><strong>${title}</strong><small>${detail}</small></div></div>`).join('')}<div class="benefit-box"><strong>Uma conversa para entender.</strong><p>A descrição inicia o contato. O escopo e as condições são combinados com você.</p></div></div></aside></div>`;}
function connectionSummary(ids) {
  const names=ids.filter(id=>store.enabled(id)).map(id=>TOOL_BY_ID[id].short);
  return names.length?'Dados atualizados em '+names.join(', ')+'.':'Alteração salva no histórico.';
}

function guidePanel() {
  if(!demonstration)return '';
  const next=demonstration.current;
  return `<section class="guide-panel" aria-label="Demonstração guiada"><div class="guide-heading"><span class="eyebrow">Veja o exemplo funcionar</span><span class="guide-count">${demonstration.index} de ${demonstration.steps.length} ações</span></div>
    <div class="guide-progress" role="progressbar" aria-valuemin="0" aria-valuemax="${demonstration.steps.length}" aria-valuenow="${demonstration.index}" aria-label="Ações demonstradas"><span style="width:${Math.round(demonstration.index/demonstration.steps.length*100)}%"></span></div>
    ${demonstration.lastResult?`<p class="guide-result" role="status">${icon('check')}${esc(demonstration.lastResult)}</p>`:''}
    <div class="guide-step"><div><h2>${next?esc(next.label):'Agora, experimente do seu jeito.'}</h2><p>${next?esc(next.detail):'Os registros do exemplo continuam nas ferramentas abaixo.'}</p></div>
    <button class="btn primary" data-action="${next?'guide-next':'guide-close'}">${next?'Mostrar esta ação':'Experimentar agora'} ${icon('arrow')}</button></div>
    ${next?'<button class="text-button" data-action="guide-close">Continuar sem o guia</button>':''}</section>`;
}

function aiBanner() {
  return `<section class="ai-banner"><div><span class="eyebrow">Automação com IA</span><h2>Veja outras possibilidades para sua rotina.</h2><p>Atendimento, leitura de documentos e escolha de ferramentas. Três exemplos simulados para experimentar.</p></div><a class="btn secondary" href="#automacoes">Ver os exemplos ${icon('arrow')}</a></section>`;
}

function automations() {
  const modes=[['atendimento','Atendimento'],['documentos','Leitura de documentos'],['sugestao','Sugestão de ferramentas']];
  if(!modes.some(([id])=>id===aiMode))aiMode='atendimento';
  const samples={atendimento:'Preciso agendar uma visita à Unidade Norte.',documentos:'Empresa: Unidade Norte\nMaterial: Lâmpadas LED\nQuantidade: 12\nResponsável: Lucas',sugestao:'Hoje digito os materiais recebidos em uma planilha e preciso conferir o estoque.'};
  const descriptions={atendimento:'Experimente uma resposta para um pedido de cliente.',documentos:'Veja informações de um documento virarem campos para conferir.',sugestao:'Descreva uma dificuldade e veja ferramentas que podem ajudar.'};
  return `<div class="page-head"><div><div class="eyebrow">Exemplos simulados</div><h1>Automação com IA.</h1><p>Experimente cenários que podem fazer parte da sua solução.</p></div></div>
    <div class="demo-notice">${icon('spark')}Simulação demonstrativa com dados de exemplo.</div>
    <div class="filters" aria-label="Escolher exemplo">${modes.map(([id,label])=>`<button class="filter ${aiMode===id?'active':''}" data-action="ai-tab" data-id="${id}" aria-pressed="${aiMode===id}">${label}</button>`).join('')}</div>
    <div class="demo-layout equal"><form class="panel" id="ai-form"><h2>${modes.find(([id])=>id===aiMode)[1]}</h2><p class="panel-subtitle">${descriptions[aiMode]}</p>${field('text',aiMode==='documentos'?'Informações do documento':'Sua mensagem',{textarea:true,value:samples[aiMode]})}<button class="btn primary full-width" type="submit">${aiMode==='documentos'?'Organizar informações':aiMode==='sugestao'?'Ver sugestão':'Ver resposta de exemplo'} ${icon('arrow')}</button></form>
    <section class="panel" aria-live="polite"><h2>Resultado do exemplo</h2><div id="ai-result">${empty('Experimente o cenário ao lado.','O resultado aparece aqui.','spark')}</div></section></div>`;
}

function runAssistant(data) {
  const output=document.getElementById('ai-result');
  if(aiMode==='documentos') {
    const fields=readDocument(data.text);
    output.innerHTML=`<p class="panel-subtitle">Confira as informações e registre na planilha de exemplo.</p>${fields.company?`<p><strong>Empresa:</strong> ${esc(fields.company)}</p>`:''}${field('ai-title','Registro',{value:fields.title})}<div class="form-row">${field('ai-quantity','Quantidade',{type:'number',value:fields.quantity,min:'1',max:'999999',step:'1'})}${field('ai-owner','Responsável',{value:fields.owner})}</div><button class="btn primary full-width" data-action="ai-register">Confirmar e atualizar planilha ${icon('table')}</button>`;
  } else if(aiMode==='sugestao') {
    const result=suggestTools(data.text);aiSuggestions=result.tools;
    output.innerHTML=`<p>${esc(result.text)}</p>${result.tools.map(id=>`<div class="suggestion-tool">${icon(TOOL_BY_ID[id].icon)}<span><strong>${esc(TOOL_BY_ID[id].short)}</strong><small>${esc(TOOL_BY_ID[id].description)}</small></span></div>`).join('')}${result.tools.length?'<button class="btn primary full-width" data-action="apply-ai-tools">Experimentar esta combinação</button>':''}`;
  } else {
    output.innerHTML=`<div class="chat-example"><div class="chat-bubble customer"><small>Pedido de exemplo</small>${esc(data.text)}</div><div class="chat-bubble"><small>Resposta simulada</small>${esc(answerMessage(data.text))}</div></div><p class="form-hint">Esse atendimento pode ser combinado com agenda, serviços e ocorrências.</p>`;
  }
}

const views={automacoes:automations,demonstracao:workspace,inicio:home,ferramentas:gallery,planilhas:sheets,servicos:services,checklists,agendamentos:appointments,etapas:approvals,ocorrencias:incidents,indicadores:indicators,comprovantes:proofs,solucao:solution,personalizada:request};
function render(scroll=false){const activeId=document.activeElement?.id,selectionStart=document.activeElement?.selectionStart,selectionEnd=document.activeElement?.selectionEnd;const id=route();if(id!=='demonstracao'&&workspaceTools.length)leaveWorkspace();main.innerHTML=views[id]();nav();if(id==='demonstracao'){document.getElementById('navigation').innerHTML=`<a class="nav-link" href="#solucao">${icon('arrow')}Alterar ferramentas</a><div class="nav-label">Meu aplicativo</div>`+workspaceTools.map(t=>`<a class="nav-link ${location.hash==='#demo-'+t?'active':''}" href="#demo-${t}">${icon(TOOL_BY_ID[t].icon)}<span>${esc(TOOL_BY_ID[t].short)}</span></a>`).join('');document.getElementById('topbar-title').textContent='Minha operação';document.getElementById('selection-bar').hidden=true;document.body.classList.remove('has-selection');}if(!scroll&&activeId){const active=document.getElementById(activeId);active?.focus({preventScroll:true});if(active?.setSelectionRange&&typeof selectionStart==='number'&&['text','search','tel'].includes(active.type))active.setSelectionRange(selectionStart,selectionEnd);}if(scroll){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}if(id==='personalizada')syncDraftPreview();updateEmbedHeight();}
function setDrawer(open){drawerOpen=open;document.getElementById('sidebar').classList.toggle('open',open);document.getElementById('sidebar').inert=!open&&window.innerWidth<=760;document.getElementById('drawer-backdrop').hidden=!open;document.getElementById('menu-button').setAttribute('aria-expanded',String(open));document.getElementById('app-shell').inert=open;document.body.style.overflow=open?'hidden':'';if(open)document.getElementById('drawer-close').focus();else document.getElementById('menu-button').focus({preventScroll:true});}
function syncDraftPreview(){const form=document.getElementById('request-form');if(!form)return;form.querySelectorAll('input[name],textarea[name]').forEach(input=>{if(Object.hasOwn(draft,input.name))draft[input.name]=input.value;});}
function preparedMessage(){syncDraftPreview();return makeWhatsAppMessage({...draft,selected:store.state.selected,referral});}
function whatsappUrl(){const phone=validatePhone(settings.whatsappNumber);if(!phone)throw new Error('O número comercial ainda precisa ser configurado.');return `https://wa.me/${phone}?text=${encodeURIComponent(preparedMessage())}`;}
function exportRows(){download(csv([['Registro','Origem','Quantidade','Responsável','Situação','Atualizado em'],...store.state.rows.map(row=>[row.title,row.type,row.quantity,row.owner,STATUS[row.status]||row.status,row.at])]),'horizon-planilha-demonstracao.csv');}
function exportReport() {
  const stats=toolStats(store.state,indicatorPeriod==='hoje');
  const standalone=store.tools.length===1&&store.enabled('indicadores');
  const has=id=>standalone||store.enabled(id);
  const counts=[['servicos','Serviços',stats.services],['servicos','Serviços concluídos',stats.completed],['ocorrencias','Ocorrências abertas',stats.openIncidents],['checklists','Inspeções concluídas',stats.inspections],['agendamentos','Compromissos agendados',stats.appointments],['planilhas','Registros em planilha',stats.rows],['comprovantes','Comprovantes',stats.proofs]];
  download(csv([['Ferramentas Horizon — relatório com dados de exemplo'],['Período',indicatorPeriod==='hoje'?'Hoje':'Todos os registros'],['Gerado em',new Date().toISOString()],['Indicador','Valor'],...counts.filter(([id])=>has(id)).map(([,label,count])=>[label,count]),...(has('etapas')?[['Processos aprovados',store.state.approvals.filter(i=>i.stage==='concluido'&&(indicatorPeriod!=='hoje'||localDay(new Date(i.at))===localDay())).length]]:[]),...(has('servicos')?[[],['Situação do serviço','Quantidade'],...Object.entries(stats.statuses).map(([status,count])=>[STATUS[status],count])]:[])]),'horizon-relatorio-demonstracao.csv');
}
function proofDetails(proof){return `<div class="demo-notice">${icon('receipt')}Comprovante demonstrativo · dados fictícios</div><div class="detail-grid"><div><small>Serviço</small>${esc(proof.title)}</div><div><small>Responsável</small>${esc(proof.owner)}</div><div><small>Registrado em</small>${time(proof.at)}</div><div><small>Situação</small>Execução registrada</div></div><h3>Observações</h3><p style="white-space:pre-wrap">${esc(proof.notes)}</p>${proof.photo&&/^data:image\/(jpeg|png|webp);base64,/.test(proof.photo)?`<img class="proof-image" src="${esc(proof.photo)}" alt="Foto da execução registrada">`:''}`;}
function proofDownload(id){const proof=store.state.proofs.find(item=>item.id===id);if(!proof)return;const html=`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Comprovante demonstrativo — Horizon</title><style>body{font:15px/1.6 Arial,sans-serif;max-width:750px;margin:35px auto;padding:25px;color:#17344d}h1{color:#087abf;font-size:25px}h3{font-size:16px}.demo-notice{padding:12px;background:#eff8fd;border-radius:10px;font-size:12px}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:25px 0}small{display:block;color:#7b94a4}img{max-width:100%;max-height:500px}.icon{display:none}</style><h1>Horizon · Comprovante de execução</h1>${proofDetails(proof)}<p style="font-size:11px;color:#7b94a4">Identificador: ${esc(proof.id)}</p></html>`;download(html,'horizon-comprovante-demonstracao.html','text/html;charset=utf-8');}
function serviceHistory(id){const service=store.state.services.find(item=>item.id===id);if(!service)return;const events=store.state.events.filter(item=>item.entityId===id||item.entityId===store.state.inspections.find(record=>record.serviceId===id)?.id);openModal('Histórico do serviço',`<div class="detail-grid"><div><small>Serviço</small>${esc(service.title)}</div><div><small>Situação</small>${badge(service.status)}</div><div><small>Unidade</small>${esc(service.client)}</div><div><small>Responsável</small>${esc(service.owner)}</div></div>${events.length?`<ul class="timeline">${events.map(item=>`<li>${esc(item.text)}<time>${time(item.at)}</time></li>`).join('')}</ul>`:'<p>Exemplo inicial. As próximas mudanças aparecerão aqui.</p>'}`);}
function shareModal(){openModal('Compartilhar Ferramentas Horizon',`<p>Envie o link da vitrine ou das ferramentas escolhidas.</p>${field('share-partner','Identificação do parceiro',{required:false,value:referral,placeholder:'Opcional. Ex.: parceiro-centro'})}<div class="field"><label for="share-link">Link para compartilhar</label><input class="link-input" id="share-link" readonly value="${esc(buildShareUrl(location.href,{selected:store.state.selected,referral,route:store.state.selected.length?'solucao':route()}))}"></div><div class="hero-buttons"><button class="btn primary" data-action="copy-link">Copiar link ${icon('link')}</button>${navigator.share?'<button class="btn secondary" data-action="native-share">Compartilhar</button>':''}</div><p class="modal-note">As ferramentas escolhidas e a indicação do parceiro acompanham o link.</p>`);}
function resetDialog(){openModal('Restaurar os exemplos?',`<p>Os registros e as fotos adicionados nesta demonstração serão removidos deste navegador. As ferramentas escolhidas serão mantidas.</p><div class="hero-buttons"><button class="btn secondary" data-action="close-modal">Manter exemplos</button><button class="btn primary" data-action="confirm-reset">Restaurar exemplos ${icon('reset')}</button></div>`);}
async function preparePhoto(file){if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)||file.size>12*1024*1024)throw new Error('Escolha uma foto JPEG, PNG ou WebP de até 12 MB.');const bitmap=await createImageBitmap(file);const ratio=Math.min(1,1000/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));const context=canvas.getContext('2d');context.fillStyle='#ffffff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const data=canvas.toDataURL('image/jpeg',.7);if(data.length>1200000)throw new Error('Esta foto precisa ser menor. Selecione outra.');return data;}
async function copyLink(){const input=document.getElementById('share-link');try{await navigator.clipboard.writeText(input.value);toast('Link copiado.');}catch{input.focus();input.select();toast('Selecione e copie o link. A cópia automática está indisponível.');}}
function updateEmbedHeight(){if(window.parent!==window)window.parent.postMessage({type:'horizon-preview:height',height:document.documentElement.scrollHeight},'*');}

unsubscribe=store.subscribe(()=>render());
window.addEventListener('hashchange',()=>{if(drawerOpen)setDrawer(false);render(true);});
window.addEventListener('resize',()=>{if(window.innerWidth>760&&drawerOpen)setDrawer(false);document.getElementById('sidebar').inert=window.innerWidth<=760&&!drawerOpen;updateEmbedHeight();});
document.getElementById('menu-button').innerHTML=icon('menu');document.getElementById('drawer-close').innerHTML=icon('close');document.getElementById('share-button').innerHTML=icon('share');document.getElementById('modal-close').innerHTML=icon('close');document.getElementById('custom-icon').innerHTML=icon('spark');
document.getElementById('menu-button').addEventListener('click',()=>setDrawer(!drawerOpen));document.getElementById('drawer-close').addEventListener('click',()=>setDrawer(false));document.getElementById('drawer-backdrop').addEventListener('click',()=>setDrawer(false));document.getElementById('share-button').addEventListener('click',shareModal);document.getElementById('modal-close').addEventListener('click',()=>modal.close());
modal.addEventListener('click',event=>{if(event.target===modal){const rect=modal.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)modal.close();}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&drawerOpen)setDrawer(false);if(event.key==='Tab'&&drawerOpen){const nodes=[...document.getElementById('sidebar').querySelectorAll('a[href],button:not(:disabled)')],first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
document.addEventListener('input',event=>{const input=event.target;if(input.id==='tool-search'){search=input.value;const items=filteredTools();document.getElementById('tool-gallery').innerHTML=items.length?toolCards(items):empty('Nenhuma ferramenta encontrada.','Descreva sua necessidade em Criar ferramenta personalizada.','search');document.getElementById('search-count').textContent=items.length+' ferramentas para explorar';}if(input.id==='inspection-notes')store.updateInspectionNotes(input.value);if(input.closest('#request-form')&&Object.hasOwn(draft,input.name))draft[input.name]=input.value;if(input.id==='share-partner')document.getElementById('share-link').value=buildShareUrl(location.href,{selected:store.state.selected,referral:input.value,route:store.state.selected.length?'solucao':route()});});
document.addEventListener('change',async event=>{const input=event.target;try{if(input.dataset.select){syncDraftPreview();store.toggleTool(input.dataset.select);}if(input.dataset.inspection)store.toggleInspectionItem(input.dataset.inspection);if(input.id==='proof-photo'){proofPhoto=await preparePhoto(input.files?.[0])||'';const preview=document.getElementById('photo-preview');if(preview)preview.innerHTML=proofPhoto?`<img src="${proofPhoto}" alt="Foto selecionada">`:'';}}catch(error){toast(error.message);}});
document.addEventListener('submit',async event=>{const form=event.target;if(!['record-form','service-form','appointment-form','approval-form','incident-form','proof-form','request-form','ai-form'].includes(form.id))return;event.preventDefault();if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));try{switch(form.id){
  case 'record-form':store.addRecord(data);notify('Registro incluído na planilha.');break;
  case 'service-form':store.addService(data);notify('Serviço solicitado. '+connectionSummary(['planilhas','indicadores']));break;
  case 'appointment-form':appointmentDate='';appointmentFilter='todos';store.addAppointment(data);notify('Compromisso agendado na demonstração.');break;
  case 'approval-form':store.addApproval(data);notify('Solicitação adicionada à primeira etapa.');break;
  case 'incident-form':store.addIncident(data);notify('Ocorrência registrada com responsável definido.');break;
  case 'proof-form':store.addProof({...data,photo:proofPhoto});proofPhoto='';render();notify('Execução registrada na demonstração.');break;
  case 'ai-form':runAssistant(data);break;
  case 'request-form':{syncDraftPreview();const url=whatsappUrl();const fallback=document.getElementById('whatsapp-fallback');fallback.hidden=false;fallback.innerHTML=`<p class="form-hint">Mensagem preparada. Confirme o envio no WhatsApp.</p><a class="text-button" href="${esc(url)}" target="_blank" rel="noopener">Abrir WhatsApp novamente ${icon('arrow')}</a>`;window.open(url,'_blank','noopener,noreferrer');break;}
}}catch(error){toast(error.message||'Não foi possível concluir esta ação.');}});
document.addEventListener('click',async event=>{const anchor=event.target.closest('a[href^="#"]');if(anchor&&drawerOpen)setDrawer(false);const element=event.target.closest('[data-action]');if(!element)return;const {action,id}=element.dataset;try{switch(action){
  case 'toggle-tool':syncDraftPreview();store.toggleTool(id);break;
  case 'tool-filter':toolFilter=id;render();break;
  case 'service-filter':serviceFilter=id;render();break;
  case 'appointment-filter':appointmentFilter=id;render();break;
  case 'appointment-day':appointmentDate=id;render();break;
  case 'all-dates':appointmentDate='';render();break;
  case 'indicator-period':indicatorPeriod=id;render();break;
  case 'start-service':store.setServiceStatus(id,'andamento');notify('Serviço em andamento.');break;
  case 'complete-service':store.setServiceStatus(id,'concluido');notify('Serviço concluído. '+connectionSummary(['planilhas','indicadores']));break;
  case 'pause-service':store.setServiceStatus(id,'pendente');notify('Pendência registrada.');break;
  case 'service-history':serviceHistory(id);break;
  case 'remove-record':store.removeRecord(id);notify('Registro removido da demonstração.');break;
  case 'export-rows':exportRows();break;
  case 'export-report':exportReport();break;
  case 'complete-inspection':store.completeInspection();notify('Checklist concluído. '+connectionSummary(['servicos','planilhas','indicadores']));break;
  case 'new-inspection':store.newInspection();notify('Nova inspeção pronta para conferir.');break;
  case 'appointment-complete':store.appointmentAction(id,'concluir');notify('Compromisso concluído.');break;
  case 'appointment-postpone':store.appointmentAction(id,'adiar');notify('Compromisso adiado em um dia.');break;
  case 'approval-advance':store.approvalAction(id,'avancar');notify('Processo atualizado.');break;
  case 'approval-adjust':store.approvalAction(id,'ajuste');notify('Ajuste solicitado. O processo voltou à solicitação.');break;
  case 'incident-next':store.incidentAction(id);notify('Situação da ocorrência atualizada.');break;
  case 'view-proof':{const proof=store.state.proofs.find(item=>item.id===id);if(proof)openModal('Comprovante de execução',proofDetails(proof));break;}
  case 'download-proof':proofDownload(id);break;
  case 'example-solution':store.selectTools(['checklists','servicos','planilhas','indicadores']);if(route()!=='solucao')location.hash='solucao';else render();break;
  case 'simulate':
  case 'launch-demo':
  case 'launch-guided':if(!catalogStore.state.selected.length){toast('Escolha pelo menos uma ferramenta.');break;}enterWorkspace(catalogStore.state.selected,action==='launch-guided');location.hash='demo-'+workspaceTools[0];render();break;
  case 'demo-tool':if(!TOOL_BY_ID[id])break;enterWorkspace([id],true);location.hash='demo-'+id;render();break;
  case 'start-guide':demonstration=new Demonstration(workspaceTools);render();break;
  case 'guide-next':{if(!demonstration||demonstration.finished)break;serviceFilter='todos';appointmentFilter='todos';appointmentDate='';indicatorPeriod='todos';const result=demonstration.run(store);location.hash='demo-'+result.tool;render();toast(result.result);break;}
  case 'guide-close':demonstration=null;render();break;
  case 'request-workspace':catalogStore.selectTools(workspaceTools);location.hash='personalizada';render();break;
  case 'ai-tab':aiMode=id;render();break;
  case 'apply-ai-tools':catalogStore.selectTools([...catalogStore.state.selected,...aiSuggestions]);location.hash='solucao';render();break;
  case 'ai-register':{const fields=Object.fromEntries(['title','owner','quantity'].map(name=>[name,document.getElementById('ai-'+name).value]));catalogStore.addRecord(fields);catalogStore.selectTools([...catalogStore.state.selected,'planilhas']);location.hash='planilhas';render();toast('Informações conferidas e registradas na planilha.');break;}

  case 'exit-demo':location.hash='solucao';break;
  case 'reset':resetDialog();break;
  case 'confirm-reset':proofPhoto='';store.reset();if(demonstration)demonstration=new Demonstration(workspaceTools);modal.close();render();notify('Exemplos restaurados. Sua seleção foi mantida.');break;
  case 'close-modal':modal.close();break;
  case 'preview-message':{const form=document.getElementById('request-form');if(form.reportValidity())openModal('Sua mensagem para a Horizon',`<pre class="whatsapp-preview">${esc(preparedMessage())}</pre><p class="modal-note">A mensagem será aberta no WhatsApp para você confirmar o envio.</p>`);break;}
  case 'copy-link':await copyLink();break;
  case 'native-share':await navigator.share({title:'Ferramentas Horizon',text:'Sua empresa, seu sistema. Experimente as ferramentas.',url:document.getElementById('share-link').value});break;
}}catch(error){if(error.name!=='AbortError')toast(error.message||'Não foi possível concluir esta ação.');}});

if(!location.hash)history.replaceState(null,'',location.pathname+location.search+'#inicio');
render();
document.getElementById('sidebar').inert=window.innerWidth<=760;
if(typeof ResizeObserver!=='undefined')new ResizeObserver(updateEmbedHeight).observe(main);
